<?php require '../config/database.php'; require '../includes/auth.php'; require_student();$base_path='../';$page_title='Job Listings';$jobs=$pdo->query('SELECT * FROM jobs ORDER BY created_at DESC')->fetchAll();include '../includes/header.php'; ?>
<section class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="section-title mb-0">Job opportunities</h1><p class="text-muted mb-0">Find your next internship or role.</p></div></div><input id="jobSearch" class="form-control mb-4" placeholder="Search by title, company, location, or type"><div class="row g-4"><?php foreach($jobs as $job): ?><div class="col-md-6 job-item"><article class="card job-card h-100 p-4"><div class="d-flex justify-content-between"><h4><?= htmlspecialchars($job['title']) ?></h4><span class="badge text-bg-primary align-self-start"><?= htmlspecialchars($job['job_type']) ?></span></div><div class="job-meta mb-3"><?= htmlspecialchars($job['company']) ?> &middot; <?= htmlspecialchars($job['location']) ?></div><p><?= htmlspecialchars($job['description']) ?></p><p class="small text-muted"><b>Requirements:</b> <?= htmlspecialchars($job['requirements']) ?><br><b>Salary/Stipend:</b> <?= htmlspecialchars($job['salary']) ?></p><form action="../actions/save-job.php" method="post"><input type="hidden" name="job_id" value="<?= $job['id'] ?>"><button class="btn btn-outline-primary">Save job</button></form></article></div><?php endforeach; ?><?php if(!$jobs): ?><p>No opportunities have been added yet.</p><?php endif; ?></div></section><?php include '../includes/footer.php'; ?>
